//! Humata 2's gRPC services, generated by tonic beside the message types
//! that `humata2_proto` holds, so both read as one `humata::v1` module.

pub mod humata {
    pub mod v1 {
        pub use humata2_proto::humata::v1::*;

        include!(env!("HUMATA2_TONIC_RS"));
    }
}

/// `google.protobuf.Timestamp`, as the messages carry it.
pub use humata2_proto::timestamp_proto::google::protobuf::Timestamp;
